 if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||end-start>86400000||!Number.isFinite(now)||![1,2,3,4,5].includes(effortLimit)||!Number.isFinite(spendLimit)||spendLimit<0||!['balanced','familiar','new'].includes(mode))throw Error('Choose a valid day, time window, effort comfort and spending limit.');
