 for(const [title,rows] of history){const r=rows[0].record;if(['purchase','income','preparation','relationship'].includes(r.decisionType))continue;const minutes=median(rows.map(o=>o.minutes))??Number(r.minutes),effort=median(rows.map(o=>o.effort))??Number(r.energy);const money=r.money===''||r.money===undefined?null:Number(r.money);if(!Number.isFinite(minutes)||minutes<=0||!Number.isFinite(effort)||effort<1||effort>5||money===null||!Number.isFinite(money)||money<0)continue;pool.push({id:'history:'+r.id,title:r.task,minutes,effort,money,category:'history',source:'familiar',historyIds:rows.map(o=>o.record.id),assumptions:'Time/effort use actual medians where available, otherwise saved estimates. Money uses the saved estimate. Review whether this context still fits.'});}
